        weight_surcharge := 5.00;
    ELSIF weight <= 20 THEN
        weight_surcharge := 10.00;
    ELSE
        weight_surcharge := 20.00;
    END IF;

    -- Calculate distance surcharge
    IF distance <= 0 THEN
        RAISE EXCEPTION 'Invalid distance';
    ELSIF distance <= 10 THEN
        distance_surcharge := 0;
    ELSIF distance <= 50 THEN
        distance_surcharge := 3.00;
